Projection.cv_schedule:
def cv_schedule():
    """The guaranteed cash values per $1,000 of this policy's premium period, sex and issue age, by policy year."""
    return data.cv_table().loc[(premium_period(), sex(), age_at_entry())]

Projection.nsp_schedule:
def nsp_schedule():
    """The net single premiums of this policy's sex, by attained age."""
    return data.nsp_table().loc[sex()]

Projection.mort_schedule:
def mort_schedule():
    """The guaranteed mortality rates of this policy's sex, by attained age."""
    return data.mort_table().loc[sex()]

Projection.mort_rate_guar_at:
def mort_rate_guar_at(y):
    """q^g_y: the guaranteed **annual** mortality rate at attained age y, from *mort_table.csv*.

    The shipped table is **[std]** illustrative and is *not* the 2017 CSO the notes
    name; that table is licensed and cannot be shipped here.
    """
    return float(mort_schedule().loc[y, "mort_rate"])
